    (CAST(SUM(CASE WHEN T1.type = 'gold' AND T1.issued < '1998-01-01' AS REAL) AS REAL) * 100.0 / COUNT(T1.card_id) AS percent_gold_cards_issued_before_1998
    ) AS percent_gold_cards_issued_before_1998
FROM card AS T1
